    "code": "/* ==========================================================================\n   CityLogic JavaFX Modern Dark Theme Stylesheet\n   ========================================================================== */\n\n.main-container {\n    -fx-background-color: #0b1120; /* Slate 950 */\n    -fx-font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, Helvetica, Arial, sans-serif;\n}\n\n/* Header & Top Bar */\n.header-box {\n    -fx-background-color: #0f172a; /* Slate 900 */\n    -fx-border-color: #1e293b;\n    -fx-border-width: 0 0 1 0;\n    -fx-padding: 12 20 8 20;\n}\n\n.brand-title {\n    -fx-text-fill: #f8fafc;\n    -fx-font-size: 20px;\n    -fx-font-weight: bold;\n}\n\n.brand-subtitle {\n    -fx-text-fill: #94a3b8;\n    -fx-font-size: 13px;\n}\n\n.badge-tick {\n    -fx-background-color: #1e293b;\n    -fx-text-fill: #38bdf8;\n    -fx-padding: 4 10 4 10;\n    -fx-background-radius: 999px;\n    -fx-font-size: 12px;\n    -fx-font-weight: bold;\n}\n\n.status-message {\n    -fx-text-fill: #94a3b8;\n    -fx-font-size: 12px;\n}\n\n/* Metrics HUD */\n.metrics-bar {\n    -fx-padding: 4 0 4 0;\n}\n\n.metric-card {\n    -fx-background-color: #1e293b;\n    -fx-background-radius: 8px;\n    -fx-padding: 8 14 8 14;\n    -fx-border-color: #334155;\n    -fx-border-radius: 8px;\n    -fx-border-width: 1px;\n}\n\n.metric-card-wide {\n    -fx-min-width: 190px;\n}\n\n.metric-label {\n    -fx-text-fill: #94a3b8;\n    -fx-font-size: 10px;\n    -fx-font-weight: bold;\n}\n\n.metric-val {\n    -fx-font-size: 18px;\n    -fx-font-weight: bold;\n}\n\n.metric-val-sm {\n    -fx-text-fill: #f1f5f9;\n    -fx-font-size: 13px;\n    -fx-font-weight: bold;\n}\n\n.metric-budget {\n    -fx-text-fill: #38bdf8; /* Sky 400 */\n}\n\n.metric-pop {\n    -fx-text-fill: #a78bfa; /* Violet 400 */\n}\n\n.metric-delta {\n    -fx-font-size: 11px;\n    -fx-font-weight: bold;\n}\n\n/* Progress Bars */\n.progress-happy .track {\n    -fx-background-color: #334155;\n    -fx-background-radius: 4px;\n}\n\n.progress-happy .bar {\n    -fx-background-color: linear-gradient(to right, #10b981, #34d399);\n    -fx-background-radius: 4px;\n}\n\n.progress-pollution .track {\n    -fx-background-color: #334155;\n    -fx-background-radius: 4px;\n}\n\n.progress-pollution .bar {\n    -fx-background-color: linear-gradient(to right, #f59e0b, #ef4444);\n    -fx-background-radius: 4px;\n}\n\n/* Simulation Controls */\n.sim-controls {\n    -fx-background-color: #1e293b;\n    -fx-background-radius: 8px;\n    -fx-padding: 4 12 4 12;\n    -fx-border-color: #334155;\n    -fx-border-radius: 8px;\n}\n\n.btn-step {\n    -fx-background-color: #334155;\n    -fx-text-fill: #f8fafc;\n    -fx-font-weight: bold;\n    -fx-cursor: hand;\n    -fx-background-radius: 6px;\n    -fx-padding: 6 12 6 12;\n}\n\n.btn-step:hover {\n    -fx-background-color: #475569;\n}\n\n.btn-play {\n    -fx-background-color: #2563eb;\n    -fx-text-fill: #ffffff;\n    -fx-font-weight: bold;\n    -fx-cursor: hand;\n    -fx-background-radius: 6px;\n    -fx-padding: 6 14 6 14;\n}\n\n.btn-play:hover {\n    -fx-background-color: #1d4ed8;\n}\n\n.btn-pause {\n    -fx-background-color: #f59e0b !important;\n}\n\n.speed-text {\n    -fx-text-fill: #94a3b8;\n    -fx-font-size: 11px;\n}\n\n.speed-val {\n    -fx-text-fill: #38bdf8;\n    -fx-font-size: 11px;\n    -fx-font-weight: bold;\n}\n\n/* Build Toolbar */\n.build-toolbar {\n    -fx-background-color: transparent;\n    -fx-padding: 4 0 0 0;\n}\n\n.toolbar-section-label {\n    -fx-text-fill: #94a3b8;\n    -fx-font-size: 11px;\n    -fx-font-weight: bold;\n    -fx-padding: 0 4 0 0;\n}\n\n.tool-btn {\n    -fx-background-color: #1e293b;\n    -fx-text-fill: #e2e8f0;\n    -fx-background-radius: 6px;\n    -fx-padding: 6 10 6 10;\n    -fx-cursor: hand;\n    -fx-font-size: 12px;\n    -fx-border-color: #334155;\n    -fx-border-radius: 6px;\n}\n\n.tool-btn:hover {\n    -fx-background-color: #334155;\n}\n\n.tool-btn:selected {\n    -fx-background-color: #0284c7;\n    -fx-text-fill: #ffffff;\n    -fx-border-color: #38bdf8;\n}\n\n.tool-btn-danger:selected {\n    -fx-background-color: #dc2626 !important;\n    -fx-border-color: #f87171 !important;\n}\n\n/* Canvas Area */\n.canvas-scroll-pane {\n    -fx-background-color: #0b1120;\n    -fx-border-color: transparent;\n}\n\n.canvas-scroll-pane .viewport {\n    -fx-background-color: #0b1120;\n}\n\n.canvas-container {\n    -fx-background-color: #0b1120;\n    -fx-padding: 16;\n}\n\n/* Sidebar & Titled Panes */\n.sidebar {\n    -fx-background-color: #0f172a;\n    -fx-border-color: #1e293b;\n    -fx-border-width: 0 0 0 1;\n}\n\n.panel-titled {\n    -fx-background-color: transparent;\n    -fx-text-fill: #f1f5f9;\n}\n\n.panel-titled > .title {\n    -fx-background-color: #1e293b;\n    -fx-text-fill: #f8fafc;\n    -fx-font-weight: bold;\n    -fx-background-radius: 6px 6px 0 0;\n}\n\n.panel-titled > .content {\n    -fx-background-color: #162032;\n    -fx-border-color: #1e293b;\n    -fx-border-width: 0 1 1 1;\n    -fx-background-radius: 0 0 6px 6px;\n}\n\n/* Inspector */\n.inspector-box {\n    -fx-padding: 8;\n}\n\n.inspector-header {\n    -fx-text-fill: #38bdf8;\n    -fx-font-size: 15px;\n    -fx-font-weight: bold;\n}\n\n.meta-label {\n    -fx-text-fill: #94a3b8;\n    -fx-font-size: 11px;\n}\n\n.meta-val {\n    -fx-text-fill: #f8fafc;\n    -fx-font-size: 12px;\n}\n\n.meta-val-highlight {\n    -fx-text-fill: #34d399;\n    -fx-font-size: 11px;\n    -fx-font-weight: bold;\n}\n\n.btn-secondary {\n    -fx-background-color: #334155;\n    -fx-text-fill: #f8fafc;\n    -fx-background-radius: 6px;\n    -fx-padding: 4 10 4 10;\n    -fx-cursor: hand;\n}\n\n.btn-danger-outline {\n    -fx-background-color: transparent;\n    -fx-border-color: #ef4444;\n    -fx-border-radius: 6px;\n    -fx-text-fill: #ef4444;\n    -fx-padding: 4 10 4 10;\n    -fx-cursor: hand;\n}\n\n.btn-danger-outline:hover {\n    -fx-background-color: #dc2626;\n    -fx-text-fill: #ffffff;\n}\n\n/* Policies */\n.policies-box {\n    -fx-padding: 8;\n}\n\n.policy-check {\n    -fx-text-fill: #f8fafc;\n    -fx-font-weight: bold;\n    -fx-font-size: 12px;\n}\n\n.policy-desc {\n    -fx-text-fill: #94a3b8;\n    -fx-font-size: 11px;\n    -fx-padding: 0 0 0 22px;\n}\n\n/* Log View */\n.log-list-view {\n    -fx-background-color: #0b1120;\n    -fx-border-color: #1e293b;\n    -fx-border-radius: 4px;\n}\n\n.log-list-view .list-cell {\n    -fx-background-color: #0b1120;\n    -fx-text-fill: #94a3b8;\n    -fx-font-family: monospace;\n    -fx-font-size: 11px;\n    -fx-padding: 3 6 3 6;\n}\n\n.log-list-view .list-cell:even {\n    -fx-background-color: #0f172a;\n}\n"
